WITH lines AS (SELECT id, created_at, EXPLODE_OUTER(coupon_codes) AS element FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, DATE_TRUNC('HOUR', created_at) AS hour_window, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, COUNT(*) AS event_count, COUNT_IF(element = 'VIP') AS vip_events, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2 FROM lines GROUP BY DATE_TRUNC('DAY', created_at), DATE_TRUNC('HOUR', created_at) ORDER BY distinct_ids_2 NULLS FIRST;
